#!/bin/bash
# Uninstall script for Reflect Notes
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Reflect Notes..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Reflect Notes if running..."
pkill -f "Reflect Notes" 2>/dev/null || true

# Remove /Applications/Reflect.app
echo "Removing /Applications/Reflect.app..."
if [ -d "/Applications/Reflect.app" ]; then
    rm -rf "/Applications/Reflect.app" 2>/dev/null || true
elif [ -f "/Applications/Reflect.app" ]; then
    rm -f "/Applications/Reflect.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Reflect
echo "Removing $HOME/Library/Application Support/Reflect..."
if [ -d "$HOME/Library/Application Support/Reflect" ]; then
    rm -rf "$HOME/Library/Application Support/Reflect" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Reflect" ]; then
    rm -f "$HOME/Library/Application Support/Reflect" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/app.reflect.ReflectDesktop.plist
echo "Removing $HOME/Library/Preferences/app.reflect.ReflectDesktop.plist..."
if [ -d "$HOME/Library/Preferences/app.reflect.ReflectDesktop.plist" ]; then
    rm -rf "$HOME/Library/Preferences/app.reflect.ReflectDesktop.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/app.reflect.ReflectDesktop.plist" ]; then
    rm -f "$HOME/Library/Preferences/app.reflect.ReflectDesktop.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
